extracted_code:
import sys
from typing import List

class Solution:
    def missingInteger(self, nums: List[int]) -> int:
        n = len(nums)
        # Find longest sequential prefix starting at index 0
        i = 0
        while i + 1 < n and nums[i + 1] == nums[i] + 1:
            i += 1
        # Sum of the prefix
        prefix_sum = sum(nums[:i + 1])
        # Set of existing numbers
        num_set = set(nums)
        # Find smallest missing integer >= prefix_sum
        x = prefix_sum
        while True:
            if x not in num_set:
                return x
            x += 1

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    # Support input like "[1,2,3]" or "1 2 3"
    try:
        if data[0] == '[':
            nums = eval(data)
        else:
            nums = list(map(int, data.split()))
    except Exception:
        # Fallback: try json parsing
        import json
        nums = json.loads(data)
    solution = Solution()
    result = solution.missingInteger(nums)
    print(result)

if __name__ == "__main__":
    main()

