extracted_code:
from typing import List

class Solution:
    def countPrefixSuffixPairs(self, words: List[str]) -> int:
        """
        Count pairs (i, j) with i < j such that words[i] is both a prefix and a suffix of words[j].
        """
        n = len(words)
        count = 0
        for i in range(n):
            wi = words[i]
            for j in range(i + 1, n):
                wj = words[j]
                if wj.startswith(wi) and wj.endswith(wi):
                    count += 1
        return count

class Solution:
    def countKeyChanges(self, s: str) -> int:
        if not s:
            return 0
        count = 0
        prev = s[0].lower()
        for ch in s[1:]:
            cur = ch.lower()
            if cur != prev:
                count += 1
            prev = cur
        return count

