extracted_code:
from typing import List

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        """
        Since each operation removes the current smallest element, we must
        remove all elements that are strictly less than k.  The minimum number
        of operations is simply the count of such elements.
        """
        count = 0
        for num in nums:
            if num < k:
                count += 1
        return count

import sys

def solve() -> None:
    data = sys.stdin.read().strip()
    if not data:
        return
    N = int(data)
    out_lines = []
    for x in range(N + 1):
        max_y = N - x
        for y in range(max_y + 1):
            max_z = N - x - y
            for z in range(max_z + 1):
                out_lines.append(f"{x} {y} {z}")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

