import sys

def solve() -> None:
    data = sys.stdin.read().splitlines()
    if not data:
        return
    S = data[0].strip()
    T = data[1].strip()
    n = len(S)
    ans = []
    j = 0  # index in S
    for i, ch in enumerate(T):
        if j >= n:
            break
        if ch == S[j]:
            ans.append(i + 1)  # 1-indexed position
            j += 1
    # Output the positions in ascending order
    print(' '.join(map(str, ans)))

if __name__ == "__main__":
    solve()

