extracted_code:
class Solution:
    def isSubstringPresent(self, s: str) -> bool:
        """
        Returns True if there exists a substring of length 2 in s that also
        appears as a substring of length 2 in the reverse of s.
        """
        n = len(s)
        if n < 2:
            return False

        rev = s[::-1]
        # Build a set of all length-2 substrings in the reversed string
        rev_subs = {rev[i:i+2] for i in range(n - 1)}

        # Check each length-2 substring in the original string
        for i in range(n - 1):
            if s[i:i+2] in rev_subs:
                return True

        return False

