class Solution:
    def maximumLengthSubstring(self, s: str) -> int:
        n = len(s)
        left = 0
        counts = {}
        max_len = 0

        for right, ch in enumerate(s):
            counts[ch] = counts.get(ch, 0) + 1

            # Shrink window until all counts <= 2
            while any(cnt > 2 for cnt in counts.values()):
                left_ch = s[left]
                counts[left_ch] -= 1
                if counts[left_ch] == 0:
                    del counts[left_ch]
                left += 1

            # Update maximum length
            current_len = right - left + 1
            if current_len > max_len:
                max_len = current_len

        return max_len

