from typing import List

class Solution:
    def longestMonotonicSubarray(self, nums: List[int]) -> int:
        """
        Returns the length of the longest contiguous subarray of nums that is either
        strictly increasing or strictly decreasing.
        """
        if not nums:
            return 0

        # Initialize counters for increasing and decreasing subarray lengths
        inc_len = 1
        dec_len = 1
        max_len = 1

        for i in range(1, len(nums)):
            if nums[i] > nums[i - 1]:
                inc_len += 1
            else:
                inc_len = 1

            if nums[i] < nums[i - 1]:
                dec_len += 1
            else:
                dec_len = 1

            max_len = max(max_len, inc_len, dec_len)

        return max_len
