from typing import List

class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        # Any non‑empty subarray works when k == 0
        if k == 0:
            return 1

        n = len(nums)
        best = float('inf')

        for i in range(n):
            cur_or = 0
            for j in range(i, n):
                cur_or |= nums[j]
                if cur_or >= k:
                    best = min(best, j - i + 1)
                    break  # longer subarray starting at i cannot be shorter

        return -1 if best == float('inf') else best

