class Solution:
    def findPermutationDifference(self, s: str, t: str) -> int:
        """
        Compute the sum of absolute differences between indices of each character
        in the original string s and its permutation t.
        """
        # Map each character to its index in s
        index_s = {ch: i for i, ch in enumerate(s)}
        # Map each character to its index in t
        index_t = {ch: i for i, ch in enumerate(t)}
        # Sum the absolute differences
        total = 0
        for ch in s:
            total += abs(index_s[ch] - index_t[ch])
        return total

