class Solution:
    def minimumChairs(self, s: str) -> int:
        """
        Computes the minimum number of chairs needed to accommodate all entries
        in a waiting room given a sequence of 'E' (enter) and 'L' (leave) events.
        """
        current = 0
        max_people = 0
        for event in s:
            if event == 'E':
                current += 1
                if current > max_people:
                    max_people = current
            elif event == 'L':
                current -= 1
                # current should never become negative due to valid input
            else:
                # In case of unexpected characters, ignore or raise error
                pass
        return max_people

