from typing import List

class Solution:
    def countCompleteDayPairs(self, hours: List[int]) -> int:
        # Count occurrences of each remainder modulo 24
        rem_counts = [0] * 24
        for h in hours:
            rem_counts[h % 24] += 1

        # Helper to compute n choose 2
        def comb2(n: int) -> int:
            return n * (n - 1) // 2

        # Pairs where both remainders are 0 (or 12)
        total = comb2(rem_counts[0]) + comb2(rem_counts[12])

        # Pairs where remainders are complementary (r, 24-r)
        for r in range(1, 12):
            total += rem_counts[r] * rem_counts[24 - r]

        return total

class Solution:
    def getSmallestString(self, s: str) -> str:
        n = len(s)
        for i in range(n - 1):
            # Check if the adjacent digits have the same parity
            if (int(s[i]) % 2) == (int(s[i + 1]) % 2):
                # If swapping makes the digit at position i smaller, perform swap
                if s[i] > s[i + 1]:
                    return s[:i] + s[i + 1] + s[i] + s[i + 2:]
        # No beneficial swap found
        return s

