class Solution:
    def clearDigits(self, s: str) -> str:
        """
        Removes all digits from the string by repeatedly deleting the first digit
        and the closest non-digit character to its left.
        """
        stack = []
        for ch in s:
            if ch.isdigit():
                # Remove the closest non-digit to the left
                while stack and stack[-1].isdigit():
                    # In a correct input this should not happen,
                    # but we pop any stray digits just in case.
                    stack.pop()
                if stack:
                    stack.pop()  # remove the non-digit
                # The digit itself is not added to the stack
            else:
                stack.append(ch)
        return "".join(stack)

