from typing import List

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Count occurrences of each color for each player
        player_color_counts = [dict() for _ in range(n)]
        for player, color in pick:
            color_counts = player_color_counts[player]
            color_counts[color] = color_counts.get(color, 0) + 1

        # Determine how many players win
        winning_players = 0
        for player in range(n):
            required = player + 1  # at least i+1 balls of same color
            if any(count >= required for count in player_color_counts[player].values()):
                winning_players += 1

        return winning_players

