    M = max(len(s) for s in S)

    out_lines = []
    for j in range(1, M + 1):
        # Find the largest row index r that has a character for this column
        max_r = 0
        for i in range(1, N + 1):
            if j <= len(S[i - 1]):
                r = N - i + 1
                if r > max_r:
                    max_r = r
        # Build the string for column j
        chars = []
        for r in range(1, max_r + 1):
            i0 = N - r  # 0‑based index of the string
            if j <= len(S[i0]):
                chars.append(S[i0][j - 1])
            else:
                chars.append('*')
        out_lines.append(''.join(chars))

    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
