import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    presses = []
    for _ in range(N):
        a = int(next(it))
        s = next(it)
        presses.append((a, s))

    INF = 10**9
    # dp[l][r] = minimal fatigue after current press with left at l, right at r
    dp = [[INF] * 101 for _ in range(101)]

    a0, s0 = presses[0]
    if s0 == 'L':
        for r in range(1, 101):
            dp[a0][r] = 0
    else:  # 'R'
        for l in range(1, 101):
            dp[l][a0] = 0

    for idx in range(1, N):
        a, s = presses[idx]
        newdp = [[INF] * 101 for _ in range(101)]
        if s == 'L':
            for l in range(1, 101):
                for r in range(1, 101):
                    cur = dp[l][r]
                    if cur == INF:
                        continue
                    nl = a
                    nr = r
                    cost = cur + abs(a - l)
                    if cost < newdp[nl][nr]:
                        newdp[nl][nr] = cost
        else:  # 'R'
            for l in range(1, 101):
                for r in range(1, 101):
                    cur = dp[l][r]
                    if cur == INF:
                        continue
                    nl = l
                    nr = a
                    cost = cur + abs(a - r)
                    if cost < newdp[nl][nr]:
                        newdp[nl][nr] = cost
        dp = newdp

    ans = INF
    for l in range(1, 101):
        for r in range(1, 101):
            if dp[l][r] < ans:
                ans = dp[l][r]
    print(ans)

if __name__ == "__main__":
    solve()

