class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        n = len(s)

        def count_at_most(ch: str) -> int:
            """Count substrings with at most k occurrences of character ch."""
            count = 0
            l = 0
            occ = 0
            for r in range(n):
                if s[r] == ch:
                    occ += 1
                while occ > k:
                    if s[l] == ch:
                        occ -= 1
                    l += 1
                count += r - l + 1
            return count

        # substrings with zeros <= k
        count_zeros = count_at_most('0')
        # substrings with ones <= k
        count_ones = count_at_most('1')

        # substrings with both zeros <= k and ones <= k
        count_both = 0
        l = 0
        zeros = 0
        ones = 0
        for r in range(n):
            if s[r] == '0':
                zeros += 1
            else:
                ones += 1
            while zeros > k or ones > k:
                if s[l] == '0':
                    zeros -= 1
                else:
                    ones -= 1
                l += 1
            count_both += r - l + 1

        return count_zeros + count_ones - count_both

