class Solution:
    def getFinalState(self, nums: List[int], k: int, multiplier: int) -> List[int]:
        # Perform k operations
        for _ in range(k):
            # Find index of first minimum element
            min_val = nums[0]
            min_idx = 0
            for i in range(1, len(nums)):
                if nums[i] < min_val:
                    min_val = nums[i]
                    min_idx = i
            # Replace the minimum value with its product
            nums[min_idx] = min_val * multiplier
        return nums

class Solution:
    def checkTwoChessboards(self, coordinate1: str, coordinate2: str) -> bool:
        """
        Return True if the two given chessboard squares have the same color.
        The color of a square is determined by the parity of the sum of its
        column index (a=1, b=2, ..., h=8) and its row number (1-8).
        Squares where this sum is even are black; odd sums are white.
        """
        def parity(coord: str) -> int:
            col = ord(coord[0]) - ord('a') + 1
            row = int(coord[1])
            return (col + row) % 2

        return parity(coordinate1) == parity(coordinate2)

