from typing import List

class Solution:
    def findXSum(self, nums: List[int], k: int, x: int) -> List[int]:
        n = len(nums)
        result = []
        for i in range(n - k + 1):
            window = nums[i:i+k]
            freq = {}
            for val in window:
                freq[val] = freq.get(val, 0) + 1
            # sort by frequency descending, then value descending
            sorted_items = sorted(freq.items(), key=lambda p: (-p[1], -p[0]))
            # pick top x distinct values
            top_vals = set()
            for idx, (val, _) in enumerate(sorted_items):
                if idx >= x:
                    break
                top_vals.add(val)
            # sum elements that are in top_vals
            s = sum(v for v in window if v in top_vals)
            result.append(s)
        return result

class Solution:
    def isBalanced(self, num: str) -> bool:
        """
        Determine if the sum of digits at even indices equals the sum at odd indices.
        """
        even_sum = 0
        odd_sum = 0
        for i, ch in enumerate(num):
            digit = ord(ch) - 48  # faster than int(ch)
            if i % 2 == 0:
                even_sum += digit
            else:
                odd_sum += digit
        return even_sum == odd_sum


# Example usage:
if __name__ == "__main__":
    sol = Solution()
    examples = ["1234", "24123"]
    for s in examples:
        print(f"{s!r} -> {sol.isBalanced(s)}")

