from typing import List

class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        n = len(nums)
        zero_positions = [i for i, v in enumerate(nums) if v == 0]
        directions = [-1, 1]  # left, right
        valid_count = 0

        for start in zero_positions:
            for d in directions:
                arr = nums[:]          # copy of array for this simulation
                curr = start
                dir = d

                # simulate process
                while 0 <= curr < n:
                    if arr[curr] == 0:
                        # move in current direction
                        curr += dir
                    else:
                        # decrement, reverse direction, then move
                        arr[curr] -= 1
                        dir *= -1
                        curr += dir

                # after loop, check if all elements are zero
                if all(v == 0 for v in arr):
                    valid_count += 1

        return valid_count

from typing import List

class Solution:
    def minimumSumSubarray(self, nums: List[int], l: int, r: int) -> int:
        n = len(nums)
        # Prefix sums: pref[i] = sum of nums[0:i]
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + nums[i]

        min_pos_sum = None

        for start in range(n):
            for end in range(start, n):
                length = end - start + 1
                if length < l:
                    continue
                if length > r:
                    break  # further ends will only increase length
                cur_sum = pref[end + 1] - pref[start]
                if cur_sum > 0:
                    if min_pos_sum is None or cur_sum < min_pos_sum:
                        min_pos_sum = cur_sum

        return min_pos_sum if min_pos_sum is not None else -1

