from typing import List

class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        res = []
        for p in nums:
            found = False
            max_k = p.bit_length() - 1  # largest k such that 2**k <= p
            for k in range(max_k, 0, -1):
                pow2k = 1 << k
                pow2k1 = 1 << (k + 1)
                x = p - pow2k
                if x < 0:
                    continue
                # x must have exactly k trailing ones:
                # lower k+1 bits of x equal 2**k - 1
                if x % pow2k1 == (pow2k - 1):
                    res.append(x)
                    found = True
                    break
            if not found:
                # try k = 0 case: x = p-1, must be even (i.e., trailing ones count 0)
                x0 = p - 1
                if x0 >= 0 and x0 % 2 == 0:
                    res.append(x0)
                else:
                    res.append(-1)
        return res

