class Solution:
    def possibleStringCount(self, word: str) -> int:
        # Count consecutive runs of identical characters
        runs = 1 if word else 0
        for i in range(1, len(word)):
            if word[i] != word[i - 1]:
                runs += 1
        # The number of possible original strings is 1 (no over-press)
        # plus, for each run of length L, we can reduce it by 1..L-1
        # which gives L-1 possibilities per run.
        return 1 + len(word) - runs

