    def constructTransformedArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        result = [0] * n
        for i, val in enumerate(nums):
            if val == 0:
                result[i] = 0
                continue
            steps = abs(val) % n
            if steps == 0:
                landing = i
            else:
                if val > 0:
                    landing = (i + steps) % n
                else:
                    landing = (i - steps) % n
            result[i] = nums[landing]
        return result

