from typing import List

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        # If any element is less than k, we cannot increase it
        if any(x < k for x in nums):
            return -1

        # Count distinct values greater than k
        distinct_vals = set(nums)
        count_gt_k = sum(1 for v in distinct_vals if v > k)
        return count_gt_k

from typing import List

class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        n = len(nums)
        # maximum possible operations is when we remove all elements
        max_ops = (n + 2) // 3  # ceil division
        for k in range(max_ops + 1):
            start = min(3 * k, n)
            suffix = nums[start:]
            if len(set(suffix)) == len(suffix):
                return k
        # The loop always returns, but return fallback
        return max_ops

class Solution:
    def hasMatch(self, s: str, p: str) -> bool:
        # Split pattern into prefix and suffix around '*'
        star_index = p.find('*')
        prefix = p[:star_index]
        suffix = p[star_index+1:]

        n = len(s)
        pref_len = len(prefix)
        suff_len = len(suffix)

        # Special case: pattern is just "*"
        if pref_len == 0 and suff_len == 0:
            return n > 0  # any non-empty substring matches

        # Find all start indices where prefix matches
        start_positions = []
        for i in range(n - pref_len + 1):
            if s[i:i+pref_len] == prefix:
                start_positions.append(i)

        # For each start position, try to find a matching suffix
        for start in start_positions:
            # Minimum end index to satisfy length constraint
            min_end = start + pref_len + suff_len - 1
            # Search for suffix ending at or after min_end
            for end in range(min_end, n):
                if end - suff_len + 1 < 0:
                    continue
                if s[end - suff_len + 1:end + 1] == suffix:
                    return True
        return False

