def solve() -> None:
    N_line = sys.stdin.readline()
    if not N_line:
        return
    N = int(N_line.strip())

    out_lines = []
    for r in range(1, N + 1):
        row_chars = []
        for c in range(1, N + 1):
            layer = min(r, c, N + 1 - r, N + 1 - c)
            if layer % 2 == 1:
                row_chars.append('#')
            else:
                row_chars.append('.')
        out_lines.append(''.join(row_chars))

    sys.stdout.write('\n'.join(out_lines))

