from typing import List

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        """
        Traverses a 2D grid in a zigzag pattern and returns every alternate cell value.
        """
        if not grid or not grid[0]:
            return []

        traversal = []
        rows, cols = len(grid), len(grid[0])

        for r in range(rows):
            if r % 2 == 0:  # even row: left-to-right
                for c in range(cols):
                    traversal.append(grid[r][c])
            else:           # odd row: right-to-left
                for c in range(cols - 1, -1, -1):
                    traversal.append(grid[r][c])

        # Pick every alternate element starting with the first
        return traversal[::2]

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        if k > n:
            return False
        for i in range(n - k + 1):
            char = s[i]
            # Check that all characters in the window are the same
            if all(ch == char for ch in s[i:i + k]):
                # Check left neighbor if it exists
                if i > 0 and s[i - 1] == char:
                    continue
                # Check right neighbor if it exists
                if i + k < n and s[i + k] == char:
                    continue
                return True
        return False

