class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k > n:
            return -1

        # Count of subarrays each number appears in
        count = [0] * 51  # nums[i] <= 50

        # Iterate over all subarrays of size k
        for start in range(n - k + 1):
            end = start + k
            sub_set = set(nums[start:end])  # unique elements in this subarray
            for val in sub_set:
                count[val] += 1

        # Find the largest integer with count == 1
        for val in range(50, -1, -1):
            if count[val] == 1:
                return val
        return -1

