from typing import List

class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + nums[i]

        # dp[i] = maximum number of segments for prefix [0..i]
        dp = [0] * n
        for i in range(n):
            dp[i] = 1  # at least one segment (whole prefix)
            for j in range(1, i + 1):  # last segment starts at j
                cur_sum = pref[i + 1] - pref[j]
                if j == 0:
                    dp[i] = max(dp[i], 1)
                else:
                    # look at previous segment ending at j-1
                    prev_sum = pref[j] - pref[j - 1]
                    # we need to find a partition where the last sum <= cur_sum
                    # iterate over all possible previous segment ends
                    for k in range(j):
                        if pref[j] - pref[k] <= cur_sum:
                            dp[i] = max(dp[i], dp[k] + 1)
        max_blocks = dp[n - 1]
        return n - max_blocks

class Solution:
    def findValidPair(self, s: str) -> str:
        # Precompute counts of each digit in the string
        from collections import Counter
        counts = Counter(s)

        # Iterate over adjacent pairs
        for i in range(len(s) - 1):
            a, b = s[i], s[i+1]
            if a == b:
                continue  # digits must differ

            # Each digit must appear exactly as many times as its numeric value
            if counts[a] == int(a) and counts[b] == int(b):
                return a + b

        # No valid pair found
        return ""

from typing import List

class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0
        for i, val in enumerate(nums):
            left_ok = True
            right_ok = True

            if i - k >= 0:
                left_ok = val > nums[i - k]
            if i + k < n:
                right_ok = val > nums[i + k]

            if left_ok and right_ok:
                total += val

        return total

